import networkx as nx
import itertools
G = nx.Graph()
G.add_nodes_from(range(11))
G.add_edges_from([(5,9), (2,7), (1,4), (0,8), (1,5), (1,9), (6,8), (5,6), (4,8), (7,8), (3,8)])

for r in range(4, 12):
    for subset in itertools.combinations(range(11), r):
        if len(subset) > 4:
            continue
        sub_g = G.subgraph(subset)
        if not sub_g.edges:
            continue
        if nx.node_connectivity(G) >= 4:
            print("SATISFIABLE")
            print(list(G.edges))
            break
    else:
        continue
    break
else:
    print("UNSATISFIABLE")
